from __future__ import absolute_import

from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.base import BaseClass

logger = BackgroundLogger.Instance()


class DU(BaseClass):
    """
    DU Operations
    """

    def __init__(self):
        super(DU, self).__init__()

    def get_dus_diff(self, **kwargs):
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.get_dus_diff(use_m2m=use_m2m, connection=connection)

    def get_du_state(self, **kwargs):
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.get_du_state(use_m2m=use_m2m, connection=connection)

    def get_opeartion_state_of_unlocking_du(self, **kwargs):
        operation_id = kwargs["operation_id"]
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.get_opeartion_state_of_unlocking_du(operation_id=operation_id, use_m2m=use_m2m,
                                                                       connection=connection)

    def unlock_du(self, **kwargs):
        du_id = kwargs["du_id"]
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.unlock_du(du_id=du_id, use_m2m=use_m2m, connection=connection)

    def lock_du(self, **kwargs):
        du_id = kwargs["du_id"]
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.lock_du(du_id=du_id, use_m2m=use_m2m, connection=connection)

    def get_du(self, **kwargs):
        du_id = kwargs["du_id"]
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.get_du(du_id=du_id, use_m2m=use_m2m, connection=connection)

    def get_opeartion_state_of_locking_du(self, **kwargs):
        operation_id = kwargs["operation_id"]
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.get_opeartion_state_of_unlocking_du(operation_id=operation_id, use_m2m=use_m2m,
                                                                       connection=connection)

    def get_cells_statuses(self, **kwargs):
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")
        timeout = kwargs.get("timeout", None)

        return self.factory.cu_oam.get_cells_statuses(timeout=timeout, connection=connection, use_m2m=use_m2m)

    def get_cells_summary(self, **kwargs):
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")
        timeout = kwargs.get("timeout", None)

        return self.factory.cu_oam.get_cells_summary(timeout=timeout, connection=connection, use_m2m=use_m2m)

    def get_cu_cells_diff(self, **kwargs):
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")
        timeout = kwargs.get("timeout", None)

        return self.factory.cu_oam.get_cu_cells_diff(timeout=timeout, connection=connection, use_m2m=use_m2m)

    def get_operation_state_of_cells(self, **kwargs):
        cell_type = kwargs["cell_type"]
        operation_id = kwargs["operation_id"]
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")

        if cell_type == "locking":
            return self.factory.cu_oam.get_operation_state_of_locking_cells(operation_id=operation_id,
                                                                            connection=connection, use_m2m=use_m2m)
        elif cell_type == "unlocking":
            return self.factory.cu_oam.get_operation_state_of_locking_cells(operation_id=operation_id,
                                                                            connection=connection, use_m2m=use_m2m)

    def get_x2_links_info(self, **kwargs):
        connection = kwargs.get("alias", "default")

        return self.factory.cu_oam.get_x2_links_info(connection=connection)

    def get_xn_link_status(self, **kwargs):
        connection = kwargs.get("alias", "default")
        timeout = kwargs.get("timeout", 30)
        return self.factory.cu_oam.get_xn_link_status(timeout=timeout, connection=connection)

    def cell_group_operation(self, **kwargs):
        operation = kwargs["operation"]
        cell_group_id = kwargs["cell_group_id"]
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")
        if operation == "lock":
            return self.factory.cu_oam.lock_cell_group(cell_group_id, connection=connection, use_m2m=use_m2m)
        elif operation == "unlock":
            return self.factory.cu_oam.unlock_cell_group(cell_group_id, connection=connection, use_m2m=use_m2m)

    def cells_operation(self, **kwargs):
        operation = kwargs["operation"]
        cell_ids = kwargs["cell_id"]
        use_m2m = kwargs.get("use_m2m", True)
        connection = kwargs.get("alias", "default")

        if operation == "lock":
            return self.factory.cu_oam.lock_cells(cell_ids, connection=connection, use_m2m=use_m2m)
        elif operation == "unlock":
            return self.factory.cu_oam.unlock_cells(cell_ids, connection=connection, use_m2m=use_m2m)

    def lock_links(self, **kwargs):
        link_name = kwargs["link_name"]
        ids = kwargs["ids"]
        connection = kwargs.get("alias", "default")

        if link_name == "xn":
            return self.factory.cu_oam.lock_xn_links(ids, connection)
        elif link_name == "x2":
            return self.factory.cu_oam.lock_x2_links(ids, connection)
        elif link_name == "ng":
            return self.factory.cu_oam.lock_ng_links(ids, connection)

    def unlock_links(self, **kwargs):
        link_name = kwargs["link_name"]
        ids = kwargs["ids"]
        connection = kwargs.get("alias", "default")

        if link_name == "xn":
            return self.factory.cu_oam.unlock_xn_links(ids, connection)
        elif link_name == "x2":
            return self.factory.cu_oam.unlock_x2_links(ids, connection)
        elif link_name == "ng":
            return self.factory.cu_oam.unlock_ng_links(ids, connection)
